'use strict';
const KEY='changing-species-v1';
const names=['Evolution','First ideas','Misconceptions','Lamarck','Weismann','Darwin & Wallace','Natural selection','Population model','Plant evidence','Finch evidence','Reflection'];
const labels={first:'1 · My first explanation',changes:'1 · What I think changes',lamarck:'2 · Predicted inheritance in the historical model',lamarckReason:'2 · Why the offspring prediction follows',mousePrediction:'3 · Prediction about inherited tail loss',mouseClaim:'3 · Supported conclusion',mouseLimit:'3 · What the evidence cannot establish',observation:'4 · An observation and the question it raises',orderReason:'5 · Why inheritance matters',modelPrediction:'6 · Prediction before modelling',modelEvidence:'6 · Population results and interpretation',modelLimit:'6 · Model limitation',freshL:'7 · Acquired-character prediction',freshN:'7 · Natural-selection prediction',evidenceChoice:'7 · Evidence selected',freshConclusion:'7 · Evidence-based conclusion',final:'8 · My final explanation',revision:'8 · What changed and why',question:'8 · My next question'};
function fresh(){return {version:2,scene:0,visited:[0],introMode:0,pokemonStep:0,shoreLater:false,lamarckTab:'bird',lamarckAction:false,lamarckOpen:{},mouseStep:0,plantStage:0,animalStage:0,animalRevealed:false,seedDraft:'42',answers:{},firstLocked:false,lamarckLevel:1,lamarckRevealed:false,mice:0,observationIndex:0,observed:[],order:[4,0,3,1,2],orderChecked:false,freshRevealed:false,sim:newSim(),savedRuns:[]};}
function newSim(){return {seed:42,rng:42,env:'dark',phase:'adults',generation:0,pop:Array.from({length:40},(_,i)=>i%2===0?'dark':'light'),survivors:null,last:null,history:[{g:0,dark:20,light:20,total:40,environment:'Starting population'}]};}
let state;try{state=JSON.parse(localStorage.getItem(KEY));if(!state||!state.answers||!state.sim)state=fresh();}catch(e){state=fresh();}
if(state.version!==2){const sceneMap=[1,3,4,5,6,7,8,10];state={...fresh(),...state,scene:sceneMap[state.scene]??0,visited:(state.visited||[]).map(n=>sceneMap[n]),version:2,seedDraft:String(state.sim.seed)};}
let storageWorks=true;
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageWorks=true;}catch(e){storageWorks=false;}$('#save-state').textContent=storageWorks?'Saved on this browser · export before leaving a shared device':'Browser saving unavailable · export your notebook';$('#note-count').textContent=Object.values(state.answers).filter(v=>String(v).trim()).length;}
function field(id,label,rows=3){label=label.replace(/^\d+([a-c]?\.)/,String(state.scene+1)+'$1');return `<label class="prompt" for="${id}">${label}</label><textarea id="${id}" data-answer="${id}" rows="${rows}">${esc(state.answers[id]||'')}</textarea>`;}
function choices(id,opts){return `<div class="choices" role="group" aria-label="${esc(labels[id]||id)}">${opts.map(([value,text])=>`<button data-choice="${id}" data-value="${value}" aria-pressed="${state.answers[id]===value}" class="${state.answers[id]===value?'selected':''}">${text}</button>`).join('')}</div>`;}
function head(n,title,lead){n=state.scene+1;return `<div class="scene-head"><p class="eyebrow">Case file ${String(n).padStart(2,'0')} / 11 · ${names[n-1]}</p><h1>${title}</h1><p class="lead">${lead}</p></div>`;}
function nos(text){return `<div class="nos"><strong>How science works</strong> · ${text}</div>`;}
function beetle(type,x=0,y=0,scale=1){let fill=type==='dark'?'#263f40':'#e6d4a7';return `<g transform="translate(${x} ${y}) scale(${scale})" stroke="#203a39" stroke-width="2" stroke-linecap="round"><path d="M18 20L8 12M16 30L3 29M17 40L6 48M34 20L44 12M36 30L49 29M35 40L46 48" fill="none"/><ellipse cx="26" cy="33" rx="15" ry="20" fill="${fill}"/><path d="M26 16V50" stroke="${type==='dark'?'#95aca3':'#ac9565'}"/><ellipse cx="26" cy="13" rx="10" ry="8" fill="#35504b"/><path d="M21 7L17 1M31 7L35 1"/><${type==='dark'?'path d="M21 31H31" stroke="#fff8df"':'circle cx="26" cy="32" r="4" fill="none" stroke="#203a39"'}/></g>`;}
function beetleIcon(type,cls=''){return `<svg class="${cls}" viewBox="0 0 52 58" role="img" aria-label="${type==='dark'?'Dark striped':'Pale ringed'} beetle">${beetle(type)}</svg>`;}
function shore(later=false){return `<svg viewBox="0 0 620 400" role="img" aria-label="Fictional shore beetles on ${later?'dark stones, with 16 dark and 4 pale beetles after several generations':'pale sand, with 10 dark and 10 pale beetles before a storm'}"><defs><linearGradient id="water" x2="0" y2="1"><stop stop-color="#84aaa2"/><stop offset="1" stop-color="#d2dfd0"/></linearGradient></defs><rect width="620" height="400" fill="url(#water)"/><path d="M0 118Q160 200 315 134T620 149V400H0Z" fill="${later?'#77847a':'#deccaa'}"/><path d="M0 113Q160 195 315 129T620 144" stroke="#f7f6e5" stroke-width="6" fill="none"/><path d="M0 93Q160 173 315 107T620 125" stroke="#c5d8c8" stroke-width="2" fill="none"/>${Array.from({length:24},(_,i)=>`<ellipse cx="${(i*131+39)%610}" cy="${200+(i*39)%187}" rx="${15+i%4*7}" ry="${6+i%3*5}" fill="${later?'#5e726c':'#c8b68f'}" opacity=".6" transform="rotate(${i*13} ${(i*131+39)%610} ${200+(i*39)%187})"/>`).join('')}${Array.from({length:20},(_,i)=>beetle(later?([1,8,12,19].includes(i)?'light':'dark'):(i%2===0?'light':'dark'),35+(i%5)*116,175+Math.floor(i/5)*52,.67)).join('')}<text x="28" y="35" fill="#193d3f" font-size="12" font-family="system-ui" letter-spacing="2">FIELD NOTES / A FICTIONAL SHORE</text></svg>`;}
function wader(){let tall=state.lamarckLevel===2,long=state.lamarckLevel===2?50:25;return `<svg viewBox="0 0 520 330" role="img" aria-label="Historical thought model of a wading bird using its legs ${tall?'more in deeper water':'less in shallow water'}"><rect width="520" height="330" fill="#dfe8db"/><circle cx="417" cy="66" r="30" fill="#e7cf92"/><path d="M0 ${tall?212:265}Q150 ${tall?195:250} 280 ${tall?212:265}T520 ${tall?212:265}V330H0" fill="#92b1a7"/><path d="M0 316Q200 299 520 314V330H0" fill="#c4bc97"/><g stroke="#354b43" stroke-width="5" fill="none"><path d="M230 ${265-long}L230 297L252 305M263 ${265-long}L263 295L284 299"/></g><ellipse cx="247" cy="${238-long}" rx="49" ry="28" fill="#edf0e2" stroke="#637367" stroke-width="2"/><path d="M273 ${230-long}Q286 ${186-long} 281 ${147-long}" fill="none" stroke="#e9ecdd" stroke-width="22"/><ellipse cx="285" cy="${145-long}" rx="18" ry="13" fill="#edf0e2"/><path d="M301 ${143-long}L346 ${150-long}L302 ${151-long}" fill="#b58c46"/><circle cx="292" cy="${141-long}" r="3" fill="#234640"/><path d="M227 ${224-long}q-40 6-47 28q39 11 73-4" fill="#b8c7b3"/><path d="M42 315V232m0 35l-18-23m18 41l18-38M468 316V251m0 24l-17-17" fill="none" stroke="#708e6b" stroke-width="4"/><text x="24" y="32" font-size="12" fill="#193d3f" font-family="system-ui">ILLUSTRATION OF A HISTORICAL PREDICTION</text></svg>`;}
function mouse(){return `<svg class="mouse" viewBox="0 0 100 60" aria-hidden="true"><path d="M28 34Q0 9 8 45" fill="none" stroke="#ad9581" stroke-width="3"/><ellipse cx="53" cy="32" rx="27" ry="17" fill="#e5ddc8" stroke="#576b60"/><ellipse cx="78" cy="32" rx="13" ry="10" fill="#e5ddc8" stroke="#576b60"/><circle cx="71" cy="21" r="9" fill="#cbbb9e" stroke="#576b60"/><circle cx="84" cy="29" r="2" fill="#213d3b"/><path d="M42 47H49M66 46H73" stroke="#576b60" stroke-width="3"/></svg>`;}
const observations=[{title:'Darwin · Galápagos',year:'1835',where:'Eastern Pacific',body:'Darwin collected mockingbirds on several Galápagos islands. He noticed that birds from different islands differed in appearance, even though they lived close together and resembled one another. Comparing his specimens raised questions about how the island forms were related.',question:'Why would nearby islands hold similar but distinct birds?',tag:'Compare places',x:174,y:153},{title:'Wallace · Malay Archipelago',year:'1854–1862',where:'Southeast Asia',body:'While collecting across the Malay Archipelago, Wallace compared the animals found on different islands. Western islands had many animals resembling those of Asia, while islands farther east had more Australian affinities. Sharp differences could occur across relatively narrow stretches of sea, raising questions about the islands’ histories.',question:'Could the history of places help explain the pattern?',tag:'Look for geographical patterns',x:651,y:174},{title:'Both · Individuals vary',year:'Years of collecting',where:'Within species',body:'Darwin and Wallace recognized that individuals within a species are not identical. Collections and comparisons revealed differences in traits such as size and form. If some of these differences were inherited, and affected survival or reproduction, individuals could contribute unequally to later generations.',question:'Could those differences affect who leaves offspring?',tag:'Look within a population',x:445,y:110}];
function map(){return `<svg viewBox="0 0 850 270" role="img" aria-label="Schematic world map locating Galápagos in the eastern Pacific and the Malay Archipelago in Southeast Asia; not a voyage route"><rect width="850" height="270" fill="#dce8df"/><g fill="none" stroke="#c0d2c4" stroke-width="1">${[50,100,150,200,250].map(y=>`<path d="M0 ${y}H850"/>`).join('')}${[100,200,300,400,500,600,700,800].map(x=>`<path d="M${x} 0V270"/>`).join('')}</g><g fill="#b6c8af" stroke="#f3f3dc" stroke-width="2"><path d="M83 45l53-29 70 12 55 19-25 31-42 13-13 38-19 1-23-22-19-41-34-5zM204 125l32 10 33 30-8 44-31 46-16-16-3-34-18-40zM380 65l33-24 32 16 19-14 40 20 48-20 80 7 35-10 63 25 29 38-40 17-24-9-27 29-38-5-14 25-16-33-37-29-44-5-36 7-39-17-46 11zM407 103l38-5 40 30-9 57-28 31-21-39-24-17-10-33zM668 202l39-16 38 24-7 33-37 4-29-21zM636 159l10 16-8 12-10-15zM657 183l37 2 10 7-39 1zM711 179l28 3 13 11-36-2z"/></g><path d="M174 153Q145 40 405 59M651 174Q673 33 405 59" stroke="#8c9e82" stroke-dasharray="4 7" fill="none"/>${observations.slice(0,2).map((o,i)=>`<circle cx="${o.x}" cy="${o.y}" r="${state.observationIndex===i?10:6}" fill="#9e722f" stroke="#fff9e9" stroke-width="3"/>`).join('')}<text x="125" y="182" font-size="13" fill="#244742">Galápagos</text><text x="594" y="150" font-size="13" fill="#244742">Malay Archipelago</text><text x="24" y="250" font-size="10" fill="#49675d">SCHEMATIC LOCATIONS · CONNECTING OBSERVATIONS, NOT VOYAGE ROUTES</text></svg>`;}
const cards=[['variation','Individuals in the population already vary.'],['inheritance','Some of their differences can be inherited by offspring.'],['resources','More young are produced than the available resources can support.'],['success','In this environment, some inherited traits lead to more surviving offspring.'],['change','Across generations, those traits can become more common in the population.']];
function render(){const n=state.scene;$('#chapters').innerHTML=names.map((x,i)=>`<button data-scene="${i}" class="${state.visited.includes(i)?'visited':''}" ${i===n?'aria-current="step"':''}><span>${String(i+1).padStart(2,'0')}</span>${x}</button>`).join('');$('#scene').innerHTML=scenes[n]();const scienceNote=$('#scene .nos');if(scienceNote)$('#scene').append(scienceNote);else $('#scene').insertAdjacentHTML('beforeend',nos('Scientific explanations can be revised or strengthened as evidence accumulates. Identify the observation that supports your reasoning and what further evidence would help.'));$('#prev').disabled=n===0;$('#next').disabled=n===10;$('#next span').textContent=n===10?'Investigation complete':'Continue';$('#scene-position').textContent=`Scene ${n+1} of 11 · ${names[n]}`;bind();save();}
const originalScenes=[
()=>head(1,'A shore changes. What happens next?','A storm washes pale sand away, exposing dark stone. Several generations later, dark beetles are more common. How would you explain the change?')+`<div class="split"><div><div class="artpanel" id="shore-art">${shore(false)}<div class="art-caption"><strong id="shore-label">Before the storm</strong> · The same two visible traits occur in this population.</div></div><div class="actions"><button id="before" class="primary">Before the storm</button><button id="after">Several generations later</button></div><p class="mini" style="margin-top:12px">An invented case to investigate. The pictures show different generations, not the same beetles changing colour.</p></div><div class="panel"><span class="tag">Start with your own thinking</span>${field('first','1a. Why might dark beetles become more common?',4)}<label class="prompt">2b. Which change is central to your explanation?</label>${choices('changes',[['individual','An individual changes during its life'],['offspring','Offspring inherit a changed trait'],['proportions','The proportions of traits change'],['unsure','I am not sure yet']])}<div class="actions"><button id="lock-first" class="primary">${state.firstLocked?'First explanation saved':'Keep my first explanation'}</button></div><p class="mini">This starting response is for comparison, not a score. Save it before moving on.</p>${nos('We need an explanation that connects observations. A pattern alone does not tell us its cause.')}</div></div>`,
()=>head(2,'Can organisms pass on what they acquire?','In 1809, Jean-Baptiste Lamarck proposed an account of species change. He linked changed circumstances to new habits, use or disuse of organs, and inheritance of acquired changes.')+`<div class="split"><div class="artpanel">${wader()}<div class="art-caption"><strong>A historical thought model</strong> · An illustration of the proposed mechanism, not a measured change in a real bird.</div></div><div class="panel"><span class="tag">Lamarck · 1744–1829</span><h3>Change the circumstances</h3><p class="subtle">Use or disuse: repeated use was proposed to strengthen or enlarge an organ; reduced use to weaken or reduce it.</p><div class="choices"><button id="shallow" class="${state.lamarckLevel===1?'selected':''}">Shallow water</button><button id="deep" class="${state.lamarckLevel===2?'selected':''}">Deeper water</button></div><p style="margin-top:16px">${state.lamarckLevel===2?'The bird repeatedly extends its legs to keep its body above deeper water. In this historical explanation, that use lengthens its legs during its life.':'In shallow water, the bird has less reason to extend its legs. This historical explanation predicts less of that acquired lengthening.'}</p><label class="prompt">2. If acquired leg length were inherited, what would you predict for its young?</label>${choices('lamarck',[['longer','Young begin with the acquired increase in leg length'],['same','Young do not inherit the acquired increase']])}<button id="reveal-lamarck" class="primary" style="margin-top:12px">Compare with the historical prediction</button>${state.lamarckRevealed?'<div class="feedback">Under the proposed mechanism, an increase acquired by using the legs would be passed to the young. This is a prediction to investigate, not an established rule of inheritance.</div>':''}${field('lamarckReason','Explain why your prediction follows from that mechanism.',2)}${nos('Lamarck helped make species change a scientific question. This simplified comparison represents one mechanism, not all of his ideas. He did not propose that animals simply wished traits into existence.')}</div></div>`,
()=>head(3,'A prediction meets an observation.','In 1887–1889, August Weismann investigated whether tail loss in parent mice was inherited. This later investigation helps us examine inheritance; it did not come before Darwin’s work.')+`<div class="panel"><div class="two"><div><span class="tag">Historical evidence</span><p>Parents had their tails surgically removed. Weismann then examined the tails of their offspring. The procedure is not illustrated.</p><p class="subtle">Test this specific claim: “A tail lost by a parent will be absent or shorter in its offspring.” Tail removal is not the same as use or disuse.</p></div><div><label class="prompt" style="margin-top:0">3a. What would that claim predict?</label>${choices('mousePrediction',[['reduced','Offspring have absent or shorter tails'],['normal','Offspring have ordinary tails']])}<div class="actions"><button id="reveal-mice" class="primary" ${state.mice===5?'disabled':''}>${state.mice===5?'All five breeding generations revealed':'Reveal the next breeding generation'}</button></div></div></div><div class="timeline">${[333,237,152,138,41].map((n,i)=>`<div class="generation ${i>=state.mice?'hidden-data':''}"><b>Parents G${i+1}</b>${i<state.mice?mouse():'<div class="reveal-count">?</div>'}<span>${i<state.mice?`${n} young<br>Ordinary tails`:'Offspring<br>not yet revealed'}</span></div>`).join('')}</div><p class="mini">Counts reported by Weismann (1889), pp. 432–433. Icons summarize the observations; they do not show individual measurements.</p>${state.mice?`<label class="prompt">3b. Which conclusion fits the observations?</label>${choices('mouseClaim',[['specific','Tail loss was not inherited in these observed offspring'],['all','No acquired change can ever affect any offspring'],['proof','This experiment proves every part of natural selection']])}<div id="mouse-feedback" aria-live="polite"></div>${field('mouseLimit','3c. What does this investigation leave untested?',2)}`:''}${nos('Evidence tests a particular prediction. A result can weaken a claim without establishing every part of an alternative explanation.')}</div>`,
()=>head(4,'Different journeys. A shared question.','Darwin and Wallace independently developed natural selection. Explore their observations, then connect an observation to a question that needs explaining.')+`<div class="split wide-left"><div><div class="map">${map()}</div><div class="observation-buttons">${observations.map((o,i)=>`<button data-observation="${i}" class="${state.observationIndex===i?'active':''}">${o.title}${state.observed.includes(i)?' ✓':''}</button>`).join('')}</div><div class="panel observation-content"><span class="tag">${observations[state.observationIndex].year} · ${observations[state.observationIndex].tag}</span><h3>${observations[state.observationIndex].title}</h3><p>${observations[state.observationIndex].body}</p><p class="subtle">${observations[state.observationIndex].question}</p></div></div><div><div class="panel"><p class="small-title">Ideas develop through evidence and exchange</p><p><strong>Charles Darwin</strong> collected evidence during the Beagle voyage and developed his explanation over years of work.</p><p><strong>Alfred Russel Wallace</strong> independently reached a similar explanation and sent an essay to Darwin in 1858.</p><p class="subtle">Lyell and Hooker arranged a joint presentation of their writings on 1 July 1858. Neither man had modern genetics.</p>${field('observation','4. Choose one observation. What question does it raise, and what extra evidence would help explain it?',3)}</div><details class="readmore"><summary>Optional film and accessible reading</summary><p>HHMI’s <em>The Making of a Theory</em> follows both naturalists. The full film is optional; the observation cards contain everything needed here.</p><p><a href="https://www.biointeractive.org/classroom-resources/origin-species-making-theory" target="_blank" rel="noopener">Open the original film and player</a> · <a href="https://www.biointeractive.org/sites/default/files/making-of-theory-printable-transcript.pdf" target="_blank" rel="noopener">Official transcript</a></p><p>For a short reading extension, use transcript pages 4–5, from Wallace’s observations of variation to his explanation of survival and reproduction. What two ideas does he connect?</p></details></div></div>${nos('Observations need interpretation. Differences between islands raise questions about history and relatedness; they do not, by themselves, identify the mechanism of natural selection.')}`,
()=>head(5,'Build an explanation that connects.','Drag the card handles or use the arrows to arrange a clear chain of reasoning. Focus on why each link is needed.')+`<div class="split wide-left"><div><ol class="order-list">${state.order.map((c,i)=>`<li><p>${cards[c][1]}</p><div class="move"><button data-move="${i},-1" aria-label="Move ${cards[c][0]} up" ${i===0?'disabled':''}>↑</button><button data-move="${i},1" aria-label="Move ${cards[c][0]} down" ${i===4?'disabled':''}>↓</button></div></li>`).join('')}</ol><button id="check-order" class="primary">Check my reasoning chain</button><div id="order-feedback" aria-live="polite"></div></div><div class="panel"><span class="tag">Natural selection</span><h3>Which beetles leave offspring?</h3><p>On dark stone, a less visible beetle may escape a predator more often. Surviving matters for evolution when it contributes to leaving offspring.</p><div class="two"><div>${beetleIcon('light')}<p class="mini">Pale · ring marking</p></div><div>${beetleIcon('dark')}<p class="mini">Dark · stripe marking</p></div></div>${field('causal','7a. Write a labelled sequence or short explanation connecting variation, inheritance, limited resources, reproductive success and population change.',4)}${field('orderReason','7b. If colour were not inherited, why might this explanation fail to predict colour change across generations?',3)}${nos('The explanation links variation, inheritance, resources and reproductive success. A scientific theory is a supported explanatory framework, not simply a guess.')}</div></div>`,
()=>head(6,'Follow the population, one generation at a time.','Return to the shoreline. Predict, test survival, then produce a new generation. Track the proportion of dark beetles—not just how many survive.')+`<div class="split wide-left"><div><div class="model-controls"><label>Background for the next survival test<select id="environment" ${state.sim.phase==='survivors'?'disabled':''}><option value="dark" ${state.sim.env==='dark'?'selected':''}>Dark stone</option><option value="light" ${state.sim.env==='light'?'selected':''}>Pale sand</option><option value="neutral" ${state.sim.env==='neutral'?'selected':''}>Equal survival chances</option></select></label><label>Seed for chance events<input id="seed" type="number" min="1" max="999999" value="${esc(state.seedDraft)}" style="width:110px;display:block"></label><button id="restart-model">Apply seed and restart</button><button id="keep-seed" hidden>Keep current seed</button></div><p class="mini">The seed repeats a sequence of chance events. Set it before starting. During a run, apply a new seed and restart or keep the current one. <span id="seed-status" role="status"></span></p><div class="beetle-field ${state.sim.env}" aria-label="Model population">${state.sim.pop.map((t,i)=>beetleIcon(t,state.sim.phase==='survivors'&&!state.sim.survivors.includes(i)?'dead':state.sim.generation?'newborn':'')).join('')||'<p>No beetles remain. Restart to investigate again.</p>'}</div><div class="legend"><span><i></i>Pale with ring</span><span><i class="dark"></i>Dark with stripe</span><span>Faded = did not survive</span></div><div class="three"><div class="stat"><b>${state.sim.generation}</b><span>Generation</span></div><div class="stat"><b>${state.sim.pop.length}</b><span>At start of generation</span></div><div class="stat"><b>${state.sim.pop.length?Math.round(state.sim.pop.filter(t=>t==='dark').length/state.sim.pop.length*100)+'%':'—'}</b><span>Dark at generation start</span></div></div><div class="actions"><button id="advance-model" class="primary" ${!state.sim.pop.length||state.sim.generation>=20?'disabled':''}>${state.sim.phase==='adults'?'1 · Test survival':'2 · Produce next generation'}</button><button id="save-run">Save this run to notebook</button></div><p class="feedback" id="model-status">${simStatus()}</p></div><div><div class="panel"><span class="tag">Teaching model · not field data</span><div class="graph">${graph()}</div><details class="readmore"><summary>Show counts and proportions</summary>${historyTable(state.sim.history)}</details><details class="readmore"><summary>Read the model rules</summary><p>Start with 20 dark and 20 pale beetles. On dark stone, each dark beetle has an 80% survival chance and each pale beetle 35%; pale sand reverses these chances. Equal chances gives both 60%.</p><p>Each survivor contributes four young of its own colour to an offspring pool. Up to 40 are randomly retained because space is limited. Adults are then replaced by their offspring. These rules simplify inheritance and omit mating, mutation and migration.</p><p>Chance may change proportions too. No individual changes colour. A lost colour cannot return in this model, even if the background changes. The run stops at generation 20 or extinction.</p></details>${field('modelPrediction','6a. Before testing: predict the trend on dark stone and explain why.',2)}${field('modelEvidence','6b. Run four generations on dark stone, then four on pale sand. Use two proportions to explain what happened.',3)}${field('modelLimit','6c. Name one model assumption. What would you need to investigate in real beetles?',2)}</div></div></div>${nos('Model results follow rules we chose. They help explore an explanation; real populations require independent evidence of inheritance and differences in reproductive success.')}`,
()=>head(7,'Will the explanation travel?','A new case: after several dry years, longer-rooted plants become more common. Predict with two explanations, then open the evidence.')+`<div class="split"><div><div class="artpanel">${plants()}<div class="art-caption">An invented plant investigation. The evidence below is a classroom scenario, not a published field dataset.</div></div>${field('freshL','7a. If a parent’s roots lengthened through use and that acquired change were inherited, what would its offspring inherit?',2)}${field('freshN','7b. What would natural selection predict if inherited root lengths already varied?',2)}<button id="reveal-fresh" class="primary" style="margin-top:15px">${state.freshRevealed?'Evidence opened':'Open the evidence'}</button></div><div class="panel">${state.freshRevealed?`<span class="tag">Evidence file opened</span><div class="evidence"><h3>A · Before drought</h3><p>Plants differed in root length before the dry years began.</p></div><div class="evidence"><h3>B · Under the same conditions</h3><p>Seedlings from longer-rooted parents tended to have longer roots even when both groups were raised with the same water supply, before drought exposure.</p></div><div class="evidence"><h3>C · Reproductive success</h3><p>During dry years, longer-rooted plants left more surviving offspring on average. The proportion of longer-rooted plants rose over generations.</p></div><label class="prompt">Which evidence most directly addresses inheritance?</label>${choices('evidenceChoice',[['A','A · Earlier variation'],['B','B · Common conditions'],['C','C · Offspring success']])}<div id="fresh-feedback" aria-live="polite"></div>${field('freshConclusion','7c. Why did longer-rooted plants become more common after the dry years? Compare your two predictions using at least two observations from A–C. Explain which account they support and what still needs testing.',4)}<button id="fresh-help">Check what my explanation should include</button><div id="fresh-help-text" aria-live="polite"></div>`:'<div class="empty"><h3>Predictions first.</h3><p>Record both accounts before seeing the observations. What finding would help distinguish them?</p></div>'}</div></div>${nos('An explanation becomes more useful when it accounts for a fresh case. Evidence under common conditions supports inheritance, but it does not identify a particular gene or exclude every parental effect.')}`,
()=>head(8,'What would you explain differently now?','Revisit the shoreline case. Compare your first explanation with one that uses the evidence and reasoning you have investigated.')+`<div class="two"><div class="panel"><span class="tag">Your starting point</span><div class="old-response">${esc(state.answers.first||'No first explanation was recorded. You can still explain what the investigation helped you understand.')}</div><p class="subtle" style="margin-top:15px">Your initial focus: ${esc({individual:'individual change',offspring:'inherited offspring traits',proportions:'population proportions',unsure:'not sure yet'}[state.answers.changes]||'not recorded')}</p><p class="mini">Keep this as a record of your earlier thinking. An accurate first idea can become more precise.</p></div><div class="panel"><span class="tag">Your explanation now</span>${field('final','8a. Explain how dark beetles could become more common across generations.',5)}</div></div><div class="split" style="margin-top:18px"><div>${field('revision','8b. What changed or became clearer? Name a particular observation or activity and explain its influence.',3)}${field('question','8c. What question remains, and what evidence would help answer it?',2)}</div><div class="panel"><h3>A stronger explanation earns its place.</h3><p>You made predictions, considered observations, tested a model and used an explanation on a new case.</p><p class="subtle">Scientists also compare explanations and refine them through evidence and argument. Revision is part of this work; it does not make all explanations equally supported.</p><div class="actions"><button id="finish-notebook" class="primary">Review and export my notebook</button></div><p class="mini">Your teacher assesses your reasoning in the handout or notebook. The site does not automatically grade written answers.</p></div></div>`
];
function plants(){return `<svg viewBox="0 0 580 290" role="img" aria-label="Two plants with visibly different root lengths before drought"><rect width="580" height="290" fill="#e3ead9"/><rect y="142" width="580" height="148" fill="#c7b48c"/><path d="M0 142H580" stroke="#647d55" stroke-width="4"/><g stroke="#476b47" stroke-width="6" fill="none"><path d="M175 140V48M404 140V48"/></g><g fill="#6f8e5b"><ellipse cx="153" cy="75" rx="25" ry="10" transform="rotate(30 153 75)"/><ellipse cx="196" cy="98" rx="25" ry="10" transform="rotate(-30 196 98)"/><ellipse cx="382" cy="75" rx="25" ry="10" transform="rotate(30 382 75)"/><ellipse cx="425" cy="98" rx="25" ry="10" transform="rotate(-30 425 98)"/></g><g stroke="#f5e6bd" stroke-width="4" fill="none"><path d="M175 143v47l-25 22m25-43l24 22m205-48v97l-28 26m28-102l24 26m-24 15l-32 16m32 6l27 19"/></g><text x="125" y="30" fill="#244742" font-size="14">Shorter roots</text><text x="359" y="30" fill="#244742" font-size="14">Longer roots</text></svg>`;}
function random(){state.sim.rng=(Math.imul(1664525,state.sim.rng)+1013904223)>>>0;return state.sim.rng/4294967296;}
function simStatus(){const s=state.sim;if(!s.pop.length)return 'No survivors left offspring. This model population is extinct; changing the habitat cannot recreate it.';if(s.phase==='survivors'){let d=s.survivors.filter(i=>s.pop[i]==='dark').length;return `${s.survivors.length} of ${s.pop.length} survived (${d} dark, ${s.survivors.length-d} pale). The faded beetles will leave no offspring. Next, survivors contribute young.`;}if(s.last)return `${s.last.survived} parents contributed ${s.last.births} young; ${s.pop.length} young were retained. This is a new generation, not transformed parents.`;return 'Generation 0 contains pre-existing variation: 20 dark and 20 pale beetles. Predict before testing survival.';}
function advance(){const s=state.sim;if(!s.pop.length||s.generation>=20)return;if(s.phase==='adults'){s.survivors=[];s.pop.forEach((t,i)=>{const p=s.env==='neutral'?.6:t===s.env?.8:.35;if(random()<p)s.survivors.push(i);});s.phase='survivors';}else{const pool=s.survivors.flatMap(i=>Array(4).fill(s.pop[i]));for(let i=pool.length-1;i>0;i--){let j=Math.floor(random()*(i+1));[pool[i],pool[j]]=[pool[j],pool[i]];}s.last={survived:s.survivors.length,births:pool.length};s.pop=pool.slice(0,40);s.generation++;const dark=s.pop.filter(t=>t==='dark').length;s.history.push({g:s.generation,dark,light:s.pop.length-dark,total:s.pop.length,environment:s.env});s.phase='adults';s.survivors=null;}render();$('#advance-model').focus();}
function graph(){const h=state.sim.history,w=400,ht=230,x=g=>45+g/Math.max(8,h.length-1)*325,y=p=>185-p*150;const path=type=>h.filter(r=>r.total).map((r,i)=>`${i?'L':'M'}${x(r.g)} ${y(r[type]/r.total)}`).join(' ');return `<svg viewBox="0 0 ${w} ${ht}" role="img" aria-label="Proportions of dark and pale beetles at the start of each generation. Exact values are in the counts table."><text x="45" y="18" fill="#193d3f" font-size="13">Trait proportions across generations</text>${[0,.5,1].map(p=>`<path d="M45 ${y(p)}H370" stroke="#d0d8cd"/><text x="5" y="${y(p)+4}" font-size="11" fill="#53645c">${p*100}%</text>`).join('')}<path d="M45 35V185H370" stroke="#697b6d" fill="none"/><path d="${path('dark')}" stroke="#203e40" stroke-width="3" fill="none"/><path d="${path('light')}" stroke="#986a25" stroke-dasharray="6 4" stroke-width="3" fill="none"/>${h.filter(r=>r.total).map(r=>`<circle cx="${x(r.g)}" cy="${y(r.dark/r.total)}" r="3" fill="#203e40"/>`).join('')}${Array.from({length:Math.max(8,h.length-1)+1},(_,g)=>g%2===0?`<text x="${x(g)}" y="202" text-anchor="middle" font-size="11" fill="#53645c">${g}</text>`:'').join('')}<text x="178" y="221" font-size="11" fill="#53645c">Generation</text></svg><div class="legend"><span>━ Dark</span><span style="color:#805619">┄ Pale</span></div>`;}
function historyTable(h){return `<div class="data-scroll"><table><thead><tr><th>Gen.</th><th>Dark</th><th>Pale</th><th>Dark %</th><th>Habitat used</th></tr></thead><tbody>${h.map(r=>`<tr><td>${r.g}</td><td>${r.dark}</td><td>${r.light}</td><td>${r.total?(100*r.dark/r.total).toFixed(1)+'%':'undefined'}</td><td>${esc(r.environment)}</td></tr>`).join('')}</tbody></table></div>`;}
function orderFeedback(){const pos=c=>state.order.indexOf(c);let errors=[];if(pos(0)>pos(3))errors.push('Variation needs to be present before differences in success can favour a trait.');if(pos(1)>pos(4))errors.push('Inheritance must connect successful parents with the next generation.');if(pos(2)>pos(3))errors.push('Limited resources help explain why not all young survive to reproduce.');if(pos(3)>pos(4))errors.push('Differences in reproductive success must come before the population trend they explain.');$('#order-feedback').innerHTML=`<div class="feedback">${errors.length?errors.join(' '):'Your chain connects the key ideas. The first three premises can be introduced in different orders; all must feed into unequal success and population change.'}</div>`;}
function mouseFeedback(){if(!$('#mouse-feedback')||!state.answers.mouseClaim)return;$('#mouse-feedback').innerHTML=`<div class="feedback">${state.answers.mouseClaim==='specific'?'This stays within the evidence: the observed offspring did not inherit their parents’ tail loss.':'That conclusion is broader than the observations. This study tested inherited tail loss, not every environmental effect or every mechanism of evolution.'}</div>`;}
function freshFeedback(){if(!$('#fresh-feedback')||!state.answers.evidenceChoice)return;$('#fresh-feedback').innerHTML=`<div class="feedback">${state.answers.evidenceChoice==='B'?'B compares offspring raised under common conditions. Their resemblance to parents supports inheritance, although more work would be needed to identify its basis.':state.answers.evidenceChoice==='A'?'A establishes that variation came before drought. It does not by itself show that offspring inherit it. Compare the seedlings in B.':'C connects root length with reproductive success. B more directly examines parent–offspring resemblance under common conditions.'}</div>`;}
function on(id,fn){const el=$(id);if(el)el.addEventListener('click',fn);}
function bind(){document.querySelectorAll('[data-scene]').forEach(b=>b.onclick=()=>go(+b.dataset.scene));document.querySelectorAll('[data-answer]').forEach(t=>{if(t.id==='first'&&state.firstLocked)t.readOnly=true;t.addEventListener('input',()=>{state.answers[t.dataset.answer]=t.value;save();});});document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{if(b.dataset.choice==='changes'&&state.firstLocked)return;state.answers[b.dataset.choice]=b.dataset.value;const group=b.parentElement;group.querySelectorAll('button').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',x===b?'true':'false');});save();mouseFeedback();freshFeedback();});
on('#before',()=>{ $('#shore-art').innerHTML=shore(false)+'<div class="art-caption"><strong>Before the storm</strong> · 10 dark and 10 pale in this illustrated sample.</div>';$('#before').classList.add('primary');$('#after').classList.remove('primary');});on('#after',()=>{$('#shore-art').innerHTML=shore(true)+'<div class="art-caption"><strong>Several generations later</strong> · 16 dark and 4 pale in this illustrated sample.</div>';$('#after').classList.add('primary');$('#before').classList.remove('primary');});on('#lock-first',()=>{if(!state.answers.first?.trim()){ $('#first').focus();$('#save-state').textContent='Write a first explanation before saving it.';return;}state.firstLocked=true;render();});on('#shallow',()=>{state.lamarckLevel=1;render();});on('#deep',()=>{state.lamarckLevel=2;render();});on('#reveal-lamarck',()=>{if(!state.answers.lamarck){$('#save-state').textContent='Choose a prediction first.';return;}state.lamarckRevealed=true;render();});on('#reveal-mice',()=>{if(!state.answers.mousePrediction){$('#save-state').textContent='Choose a prediction before revealing observations.';return;}state.mice=Math.min(5,state.mice+1);render();});document.querySelectorAll('[data-observation]').forEach(b=>b.onclick=()=>{state.observationIndex=+b.dataset.observation;if(!state.observed.includes(state.observationIndex))state.observed.push(state.observationIndex);render();});document.querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>{const [i,dir]=b.dataset.move.split(',').map(Number);[state.order[i],state.order[i+dir]]=[state.order[i+dir],state.order[i]];state.orderChecked=false;render();document.querySelector(`[data-move="${i+dir},${dir}"]`)?.focus();});on('#check-order',()=>{state.orderChecked=true;save();orderFeedback();});if(state.orderChecked&&$('#order-feedback'))orderFeedback();on('#advance-model',advance);if($('#environment'))$('#environment').onchange=e=>{state.sim.env=e.target.value;render();};on('#restart-model',()=>{const seed=Math.max(1,Math.min(999999,Math.floor(Number($('#seed').value)||42)));const env=state.sim.env;state.sim=newSim();state.sim.env=env;state.sim.seed=seed;state.sim.rng=seed;render();});on('#save-run',()=>{state.savedRuns.push(JSON.parse(JSON.stringify({seed:state.sim.seed,history:state.sim.history})));if(state.savedRuns.length>12)state.savedRuns.shift();save();$('#model-status').textContent=`Run saved to notebook (${state.savedRuns.length} saved). Your live model is unchanged.`;});on('#reveal-fresh',()=>{if(!state.answers.freshL?.trim()||!state.answers.freshN?.trim()){$('#save-state').textContent='Record both predictions before opening the evidence.';return;}state.freshRevealed=true;render();});on('#fresh-help',()=>{$('#fresh-help-text').innerHTML='<div class="feedback">Check for: variation before drought (A), evidence supporting inheritance (B), more surviving offspring (C), and a change in population proportions. Connect these to the predictions. A claim that every plant grew the roots it needed does not explain all three observations. Your teacher will assess the written reasoning.</div>';});on('#finish-notebook',notebook);mouseFeedback();freshFeedback();}
function go(n){if(state.scene===1&&n!==1&&state.answers.first?.trim())state.firstLocked=true;state.scene=Math.max(0,Math.min(10,n));if(!state.visited.includes(state.scene))state.visited.push(state.scene);if(state.scene===5&&!state.observed.includes(state.observationIndex))state.observed.push(state.observationIndex);render();$('#scene').focus();window.scrollTo({top:0,behavior:'instant'});}
function showDialog(title,html){$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=html;$('#dialog').showModal();}
function recordHTML(){return `<h1>The Case of the Changing Species</h1><p>Student evidence notebook · ${new Date().toLocaleDateString()}</p>${Object.entries(labels).sort((a,b)=>parseInt(a[1])-parseInt(b[1])).map(([k,l])=>`<div class="record-item"><h3>${l}</h3><p>${esc(state.answers[k]||'Not recorded')}</p></div>`).join('')}<h2>Historical observations revealed</h2><p>${[333,237,152,138,41].slice(0,state.mice).map((n,i)=>`Parents G${i+1}: ${n} young, ordinary tails`).join('<br>')||'Not yet revealed'}</p><h2>Reasoning card order</h2><ol>${state.order.map(c=>`<li>${cards[c][1]}</li>`).join('')}</ol><h2>Current population model</h2><p>Seed ${state.sim.seed} · ${state.sim.phase==='survivors'?'Survival phase; current offspring generation not yet produced':'Completed generations'}</p>${historyTable(state.sim.history)}${state.savedRuns.map((r,i)=>`<h2>Saved run ${i+1}</h2><p>Seed ${r.seed}</p>${historyTable(r.history)}`).join('')}`;}
function recordText(){return 'The Case of the Changing Species\nStudent evidence notebook\n\n'+Object.entries(labels).sort((a,b)=>parseInt(a[1])-parseInt(b[1])).map(([k,l])=>l+'\n'+(state.answers[k]||'Not recorded')).join('\n\n')+'\n\nReasoning card order\n'+state.order.map((c,i)=>(i+1)+'. '+cards[c][1]).join('\n')+'\n\nHistorical observations revealed\n'+[333,237,152,138,41].slice(0,state.mice).map((n,i)=>'Parents G'+(i+1)+': '+n+' young, ordinary tails').join('\n')+'\n\nModel runs\n'+[...state.savedRuns,{seed:state.sim.seed,history:state.sim.history}].map((r,i)=>'Run '+(i+1)+' · Seed '+r.seed+'\n'+r.history.map(h=>'Generation '+h.g+': dark '+h.dark+', pale '+h.light+', dark proportion '+(h.total?(100*h.dark/h.total).toFixed(1)+'%':'undefined')+', habitat '+h.environment).join('\n')).join('\n\n');}
function notebook(){showDialog('Your evidence notebook',`<p class="subtle">Responses belong to this browser profile. Export a copy before closing a private window or leaving a shared device. Written responses are not automatically graded.</p><div class="actions"><button id="download-notes" class="primary">Download text record</button><button id="print-notes">Print or save as PDF</button><button id="download-data">Download model CSV</button></div>${recordHTML()}`);on('#download-notes',()=>{download('Changing_Species_Notebook.txt',recordText(),'text/plain');});on('#print-notes',()=>{$('#print-record').innerHTML=recordHTML();window.print();});on('#download-data',()=>{let out='run,seed,generation,dark,pale,total,dark_percent,environment\n';[...state.savedRuns,{seed:state.sim.seed,history:state.sim.history}].forEach((r,i)=>r.history.forEach(h=>out+=`${i+1},${r.seed},${h.g},${h.dark},${h.light},${h.total},${h.total?(100*h.dark/h.total).toFixed(2):''},${h.environment}\n`));download('Changing_Species_Model.csv',out,'text/csv');});}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('#prev').onclick=()=>go(state.scene-1);$('#next').onclick=()=>go(state.scene+1);$('.brand').onclick=e=>{e.preventDefault();go(0);};$('#close').onclick=()=>$('#dialog').close();$('#notebook').onclick=notebook;$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=$('#dialog').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#dialog').close();}});document.addEventListener('keydown',e=>{if($('#dialog').open||e.altKey||e.ctrlKey||e.metaKey||['INPUT','TEXTAREA','SELECT','BUTTON'].includes(document.activeElement.tagName))return;if(e.key==='ArrowRight'){e.preventDefault();go(state.scene+1);}if(e.key==='ArrowLeft'){e.preventDefault();go(state.scene-1);}});
$('#reset').onclick=()=>{showDialog('Start a new investigation?',`<p>This clears the responses and model runs saved on this browser. Download your notebook first if you want to keep it.</p><div class="actions"><button id="confirm-reset" class="primary">Clear and start over</button><button id="cancel-reset">Keep my work</button></div>`);on('#cancel-reset',()=>$('#dialog').close());on('#confirm-reset',()=>{state=fresh();$('#dialog').close();render();window.scrollTo(0,0);});};
$('#terms').onclick=()=>showDialog('Words for the investigation',`<dl><dt><strong>Population</strong></dt><dd>A group of the same species living in an area.</dd><dt><strong>Variation</strong></dt><dd>Differences among individuals in a population.</dd><dt><strong>Heritable</strong></dt><dd>Able to be passed from parents to offspring through inheritance.</dd><dt><strong>Acquired characteristic</strong></dt><dd>A feature gained or changed during an individual’s life, such as muscle developed through exercise. Acquired does not automatically mean inherited.</dd><dt><strong>Generation</strong></dt><dd>A group of offspring that follows its parent generation.</dd><dt><strong>Proportion</strong></dt><dd>A part compared with the whole. If 12 of 40 beetles are dark, the dark proportion is 12 ÷ 40 = 30%.</dd><dt><strong>Natural selection</strong></dt><dd>Differences in survival and reproductive success associated with heritable variation, which can change a population across generations.</dd><dt><strong>Fitness</strong></dt><dd>Reproductive success in a particular environment; not simply strength.</dd><dt><strong>Prediction</strong></dt><dd>An expected observation if an explanation and its assumptions are correct.</dd><dt><strong>Model</strong></dt><dd>A simplified representation used to explore ideas. Its conclusions depend on its rules.</dd></dl>`);
$('#sources').onclick=()=>showDialog('Sources and model notes',`<p>Created for Ethan Josey’s EDSE 455 resource. The shore beetles, plant and finch cases, drawn illustrations, notebook and model are original teaching materials. Third-party images are credited below. Historical observations are identified separately.</p><ul><li>Jensen, M. S., & Finley, F. N. (1995). Teaching evolution using historical arguments in a conceptual change strategy. <em>Science Education, 79</em>(2), 147–166. <a href="https://doi.org/10.1002/sce.3730790203" target="_blank" rel="noopener">Paper</a>. The sequence adapts its teaching approach; the study did not evaluate this website.</li><li>Weismann, A. (1889). <em>Essays upon heredity and kindred biological problems</em>, pp. 432–434. <a href="https://www.gutenberg.org/files/48132/48132-h/48132-h.htm" target="_blank" rel="noopener">Original account</a>. Our chart uses the five reported offspring counts. Unlike the 1995 article’s brief retelling, the original account identifies mice. The injury experiment is not a direct test of use and disuse.</li><li>Darwin, C. R., & Wallace, A. R. (1858). On the tendency of species to form varieties; and on the perpetuation of varieties and species by natural means of selection. <a href="https://darwin-online.org.uk/converted/published/1858_species_F350.html" target="_blank" rel="noopener">Original writings and editorial history</a>.</li><li>HHMI BioInteractive. <em>The Origin of Species: The Making of a Theory</em> (2013), <a href="https://www.biointeractive.org/classroom-resources/origin-species-making-theory" target="_blank" rel="noopener">film and transcript</a>; <a href="https://www.biointeractive.org/classroom-resources/identifying-patterns-observations" target="_blank" rel="noopener">Identifying Patterns in Observations</a> (2014). Used to inform observation-to-argument design. The film uses its official hosted player and links; no video file is copied.</li></ul><h3>Reading the model</h3><p>Two fixed colour types, simplified single-parent inheritance, independent chance of survival and a random density limit of 40. Survival chances are chosen for visibility, not measured from real beetles. No mutation, migration or mating. Four young per survivor create an offspring pool; up to 40 are randomly retained. Colour loss is irreversible within a run.</p><p>The chronological order is intentionally rearranged: Weismann’s later evidence comes before the Darwin–Wallace scene to support the investigation. Darwin also considered other mechanisms; neither historical account is represented here in full.</p><p><a href="materials/Teacher_Guide.docx">Teacher guide</a> · <a href="MODEL.md">Detailed model rules</a> · <a href="README.md">Running and publishing</a></p>`);

