 const cards=[...document.querySelectorAll('.order-list li')];cards.forEach((li,i)=>{const handle=document.createElement('button');handle.className='drag-handle';handle.type='button';handle.setAttribute('aria-label','Drag card '+(i+1)+' to reorder. Use the arrow buttons for keyboard control.');handle.textContent='⠿ Drag';li.prepend(handle);let active=false,target=i;handle.onpointerdown=e=>{if(e.button!==0)return;active=true;target=i;handle.setPointerCapture(e.pointerId);li.classList.add('dragging');e.preventDefault();};handle.onpointermove=e=>{if(!active)return;cards.forEach((card,j)=>{const r=card.getBoundingClientRect();if(e.clientY>=r.top&&e.clientY<=r.bottom)target=j;card.classList.toggle('drop-target',target===j&&j!==i);});if(e.clientY<70)window.scrollBy(0,-15);else if(e.clientY>innerHeight-70)window.scrollBy(0,15);};handle.onpointerup=e=>{if(!active)return;active=false;if(target!==i){const item=state.order.splice(i,1)[0];state.order.splice(target,0,item);state.orderChecked=false;render();$('.order-list li:nth-child('+(target+1)+') .drag-handle')?.focus();}else cards.forEach(c=>c.classList.remove('dragging','drop-target'));};handle.onpointercancel=()=>{active=false;cards.forEach(c=>c.classList.remove('dragging','drop-target'));};});
 if(state.scene===5&&state.observationIndex<2){const i=state.observationIndex;$('.observation-content').insertAdjacentHTML('beforeend',`<figure class="species-photo"><img src="assets/${i===0?'mockingbird.jpg':'butterfly-supplied.png'}" alt="${i===0?'Galápagos mockingbird photographed on Genovesa':'Rajah Brooke’s birdwing butterfly with black and green wings'}"><figcaption>${i===0?'A Galápagos mockingbird. Charles J. Sharp, CC BY-SA 3.0.':'Rajah Brooke’s birdwing, a species described by Wallace in 1855. Photo: CheongWeei Gan, 2022 · CC BY 4.0.'} A modern photograph; not from the naturalist’s collection.</figcaption></figure>`);}
